  // open confirmation dialog and wait for response
  this.$refs.confirm.open(
    'Unsaved Changes',
    'You have unsaved changes in your Continue Out. Do you want to exit your filing?',
    {
      width: '45rem',
      persistent: true,
      yes: 'Return to my filing',
      no: null,
      cancel: 'Exit without saving'
    }
  ).then(() => {
    // if we get here, Yes was clicked
    // nothing to do
  }).catch(() => {
    // if we get here, Cancel was clicked
    // ignore changes
    this.haveChanges = false
    // route to dashboard
    this.navigateToBusinessDashboard(this.getIdentifier)
  })
}

watch(() => state.emailBodyText, () => {
  if (state.emailBodyText) state.haveUnsavedChanges = true
})

